CALL pg_temp.version_write('claim player career',$cmd$SELECT public.claim_player_career_base_atomic(players[12]) FROM version_fixture$cmd$);
CALL pg_temp.version_write('complete player career',$cmd$SELECT public.complete_player_career_base_atomic(players[12],NULL,NULL,5,9561,9562) FROM version_fixture$cmd$);
CALL pg_temp.version_write('assign NBA identity',$cmd$SELECT public.assign_player_nba_id_atomic(players[11],'version-nba-identity') FROM version_fixture$cmd$);
CALL pg_temp.version_write('link player identity',$cmd$SELECT public.link_player_sources_atomic('espn',jsonb_build_array(jsonb_build_object('provider_id','version-espn-identity','display_name',(SELECT display_name FROM public.players WHERE id=f.players[11]),'nba_team','BOS','years_exp',0))) FROM version_fixture f$cmd$);
CALL pg_temp.version_write('import player identity',$cmd$SELECT public.resolve_player_imports_atomic('nba_cdn',jsonb_build_array(jsonb_build_object('provider_id','version-import-identity','display_name','Version '||gen_random_uuid()::text)))$cmd$);
CALL pg_temp.version_write('dynasty rankings worker',$cmd$SELECT public.replace_dynasty_rankings('version-fixture',now(),jsonb_build_array(jsonb_build_object('source_rank',1,'source_player_name',(SELECT display_name FROM public.players WHERE id=f.players[10]),'player_id',players[10])),1) FROM version_fixture f$cmd$);
CALL pg_temp.version_write('save trade estimate',$cmd$SELECT public.save_trade_estimate_quote(user_ids[1],member_ids[1],jsonb_build_object('leagueId',league_id,'seasonId',season_id,'seasonYear',9562,'terms','{}'::jsonb),'{"teams":[],"assets":[]}','version-model') FROM version_fixture$cmd$);
